import Vue from 'vue'
import Vuex from 'vuex'

Vue.use(Vuex)

export default new Vuex.Store({
  state: {
    authState: {
      token: localStorage.getItem('token-medic') || '',
      loggedMedic: JSON.parse(localStorage.getItem('logged-medic')) || '',
    },
    settings: {},
    menuOpen: false,
    commingVideochat: null
  },
  getters: {
    isAuthenticated: state => !!state.authState.token,
    loggedMedic: state => state.authState.loggedMedic,
    settings: state => state.settings,
    menuOpen: state => state.menuOpen,
    commingVideochat: state => state.commingVideochat,
  },
  mutations: {
    updateLogged(state, loggedMedic ) {
      state.authState.loggedMedic = loggedMedic;
    },
    authSuccess(state, {token, loggedMedic} ) {
      state.authState.token = token;
      state.authState.loggedMedic = loggedMedic;
    },
    logout(state) {
      state.authState.token = '';
      state.authState.loggedMedic = {};
      localStorage.removeItem('logged-medic');
      localStorage.removeItem('token-medic');
    },
    storeSettings(state,settings){
      state.settings = settings;
    },
    toggleMenu (state){
      state.menuOpen = !state.menuOpen
    },
    setCommingVideochat(state, commingVideochat ) {
      state.commingVideochat = commingVideochat;
    },
  },
  actions: {
    
  }
})