<template>
<div id="app">
    <router-view :key="$route.fullPath" />
</div>
</template>

<script>
import gql from 'graphql-tag'
import { mapMutations, mapGetters } from 'vuex'
import mixins from '@/mixins/mixins'
import listMixins from '@/mixins/listMixins'

export default {
	name: 'App',
	metaInfo: {
        titleTemplate: '%s - Recetalia',
        title: 'Gestión de doctores',
        htmlAttrs: {
            lang: 'es',
            amp: true
        }
	},
	mixins:[mixins, listMixins],
	computed: {
		...mapGetters(['isAuthenticated','loggedMedic'])
	},
	beforeMount() {
        this.loadMe();
    },
	updated() {
		this.loadMe();
	},
	mounted(){
        // console.log(this.$installer)
    },
	methods:{
		...mapMutations(['updateLogged']),
		loadMe(){
			if( this.isAuthenticated){
				this.$apollo.query({
					query: gql`query{
						medicLogged {
							id
							name
							lastname
							email
						}
					}`,
					fetchPolicy: 'no-cache'
				})
				.then(({data}) => {
					if(data.medicLogged){
						this.updateLogged(data.medicLogged);
					}else{
						this.$router.push('/logout');
					}
				});
			}else{
				// if(this.$route.name!='login' && this.$route.name!='register' && this.$route.name!='logout' && this.$route.name!='forgot-password'){
				// 	this.$router.push('/logout');
				// }
			}
		},
		
		
	}
}
</script>

